// static
bool UnionTraits<::ai_overlay_dialog::mojom::PageHandler_ExecuteWebMcpTool_ResponseParam_Result::DataView, ::ai_overlay_dialog::mojom::PageHandler_ExecuteWebMcpTool_ResponseParam_ResultPtr>::Read(
    ::ai_overlay_dialog::mojom::PageHandler_ExecuteWebMcpTool_ResponseParam_Result::DataView input,
    ::ai_overlay_dialog::mojom::PageHandler_ExecuteWebMcpTool_ResponseParam_ResultPtr* output) {
  using UnionType = ::ai_overlay_dialog::mojom::PageHandler_ExecuteWebMcpTool_ResponseParam_Result;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kSuccess: {
      ::base::Value result_success{};
      if (!input.ReadSuccess(&result_success))
        return false;

      *output = UnionType::NewSuccess(
          std::move(result_success));
      break;
    }
    case Tag::kFailure: {
      std::string result_failure{};
      if (!input.ReadFailure(&result_failure))
        return false;

      *output = UnionType::NewFailure(
          std::move(result_failure));
      break;
    }
    default:

      return false;
  }
  return true;
}

